<?php $pageTitle='Player Profile';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';$id=filter_var($_GET['id']??0,FILTER_VALIDATE_INT);$db=getDB();$q=$db->prepare('SELECT * FROM players WHERE id=? AND club_id=?');$q->execute([$id,$_SESSION['club_id']]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Player not found.');}$q=$db->prepare("SELECT s.*,t.table_number FROM sessions s JOIN tables t ON t.id=s.table_id WHERE s.player_id=? AND s.status='completed' ORDER BY s.end_time DESC LIMIT 30");$q->execute([$id]);$sessions=$q->fetchAll();?><a href="<?=url('modules/players.php')?>" class="text-slate-400 text-sm"><i class="fa-solid fa-arrow-left mr-1"></i>Back to players</a><section class="card mt-4"><div class="flex flex-wrap gap-5 items-center"><div class="w-20 h-20 rounded-full bg-green-500/20 text-green-400 text-3xl font-bold flex items-center justify-center"><?=strtoupper(substr($p['name'],0,1))?></div><div><h1 class="text-3xl font-bold"><?=sanitize($p['name'])?></h1><p class="text-slate-400"><?=sanitize($p['phone'])?> · Member since <?=date('M Y',strtotime($p['joined_date']??$p['created_at']))?></p><span class="inline-block mt-2 px-2 py-1 bg-slate-700 rounded text-xs uppercase"><?=sanitize($p['tier'])?></span></div></div><div class="grid grid-cols-2 lg:grid-cols-5 gap-4 mt-6"><?php foreach([['Total Visits',$p['total_visits']],['Total Spent',money($p['total_spent'])],['Loyalty Points',$p['loyalty_points']],['Ledger Balance',money($p['ledger_balance'])],['Redeemable',money($p['loyalty_points'])]] as [$l,$v]):?><div class="bg-slate-900 p-4 rounded-lg"><p class="text-xs uppercase text-slate-500"><?=$l?></p><b class="text-lg block mt-1"><?=$v?></b></div><?php endforeach?></div></section><section class="card mt-5 overflow-x-auto"><h2 class="font-bold mb-3">Visit History</h2><table class="data-table w-full"><thead><tr><th>Date</th><th>Table</th><th>Duration</th><th>Amount</th><th>Payment</th><th>Points</th></tr></thead><tbody><?php foreach($sessions as $s):?><tr><td><?=date('d M Y',strtotime($s['end_time']))?></td><td><?=$s['table_number']?></td><td><?=gmdate('H:i',max(0,strtotime($s['end_time'])-strtotime($s['start_time'])-$s['total_pause_seconds']))?></td><td><?=money($s['total_amount'])?></td><td><?=ucfirst($s['payment_method'])?></td><td>+<?=$s['points_earned']?></td></tr><?php endforeach?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
